<script>
  const {
    id,
    angle,
    stops = 2, // Or an array with the actual stop percentages
  } = $props()

  const _stops = $derived(
    (Array.isArray(stops) ? stops : Array(stops).fill({})).map(
      (stop, index) => ({
        offset: stop.offset || `${(index * 100) / (stops - 1)}%`,
        'stop-color': stop.color || `var(--gradient-stop-${index + 1})`,
      }),
    ),
  )
</script>

<!-- Inspiration -->
<!-- https://fvsch.com/svg-gradient-fill -->
<svg
  style="position:absolute; width:0; height:0; overflow:hidden"
  aria-hidden="true"
  focusable="false"
  height="0"
  width="0"
>
  <defs>
    <linearGradient
      {id}
      gradientTransform="rotate({angle} 0.5 0.5)"
      x2="0"
      y1="1"
    >
      {#each _stops as stop (stop.offset)}
        <stop {...stop}></stop>
      {/each}
    </linearGradient>
  </defs>
</svg>
